
import Foundation
import CocoaLumberjackSwift

/**
 *
 * Nexi Payments
 *
 * Some functionalities must be implemented at the
 * backend level by the client.
 * References are provided as examples.
 *
 */
class BackendService {
    
    /**
     *
     * Example of the method used to receive
     * the requesturi from Nexi servers.
     *
     * Please note that the deviceId is generated by the SDK;
     * do not confuse it with the Android operating system's device ID.
     *
     */
    static func getRequestUri(deviceId : String) async throws -> String {
        
        DDLogInfo("\(Constant.APP_MANAGER) -> start getRequestUri(\(deviceId)")
        
        // The backend web address.
        let strURLBackend = "https://<yoursite>/<yourmethod>"
        
        guard let url = URL(string: strURLBackend)
            else {
                throw NetworkError.invalidURL
        }

        var request = URLRequest(url: url)
        request.httpMethod = "GET"
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        
        do {
           
            let (data, response) =  try await URLSession.shared.data(for: request)
           
            guard let httpResponse = response as? HTTPURLResponse, (200...299).contains(httpResponse.statusCode) else {
                
                if let httpResponse = response as? HTTPURLResponse {
                    
                    DDLogError("\(Constant.APP_MANAGER) -> error \(httpResponse.statusCode)")
                    
                }
                
                throw NetworkError.invalidResponse
            }

            do {
                
                let decoder = JSONDecoder()
                
                let requestURIObject = try decoder.decode(RequestURI.self, from: data)
                
                DDLogInfo("\(Constant.APP_MANAGER) -> request_uri : \(requestURIObject.request_uri)")
                
                return requestURIObject.request_uri
                
            } catch {
                
                DDLogError("\(Constant.APP_MANAGER) -> errore \(NetworkError.decodingError)")
                
                throw NetworkError.decodingError
            }
            
        } catch {
            
            DDLogError("\(Constant.APP_MANAGER) -> errore \(NetworkError.decodingError)")
            
            throw NetworkError.requestFailed(error)
        }
        
    } // func getRequestUri(deviceId : String, idUtente : Int)
}
